import{_ as o,C as a,o as s,c as i,a5 as n,E as r}from"./chunks/framework.CDWg-b0B.js";const b=JSON.parse('{"title":"awesome-ai-agents","description":"A list of AI autonomous agents","frontmatter":{"title":"awesome-ai-agents","url":"https://github.com/e2b-dev/awesome-ai-agents","stars":30326,"stars_as_of":"2026-10-10T00:00:00.000Z","stars_source":"github-rest-api","type":"agents","categories":["ai","agents"],"tags":["agent","ai","artificial-intelligence","autogpt","autonomous-agents","babyagi","gpt","gpt-engineer","openai","python","awesome-ai-agents"],"description":"A list of AI autonomous agents","license":"unspecified","head":[["link",{"rel":"canonical","href":"https://awesome.rairahulr1.com/repos/awesome-ai-agents"}],["meta",{"name":"description","content":"A list of AI autonomous agents"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"awesome-ai-agents · awesomes"}],["meta",{"property":"og:description","content":"A list of AI autonomous agents"}],["meta",{"property":"og:url","content":"https://awesome.rairahulr1.com/repos/awesome-ai-agents"}],["meta",{"name":"twitter:card","content":"summary"}],["meta",{"name":"twitter:title","content":"awesome-ai-agents · awesomes"}],["meta",{"name":"twitter:description","content":"A list of AI autonomous agents"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"SoftwareSourceCode\\",\\"name\\":\\"awesome-ai-agents\\",\\"description\\":\\"A list of AI autonomous agents\\",\\"codeRepository\\":\\"https://github.com/e2b-dev/awesome-ai-agents\\",\\"license\\":\\"unspecified\\",\\"interactionStatistic\\":{\\"@type\\":\\"InteractionCounter\\",\\"interactionType\\":\\"https://schema.org/LikeAction\\",\\"userInteractionCount\\":30326}}"]]},"headers":[],"relativePath":"repos/awesome-ai-agents.md","filePath":"repos/awesome-ai-agents.md","lastUpdated":1791637702000}'),c={name:"repos/awesome-ai-agents.md"};function d(l,e,h,p,u,g){const t=a("Comments");return s(),i("div",null,[e[0]||(e[0]=n('<h1 id="awesome-ai-agents" tabindex="-1">awesome-ai-agents <a class="header-anchor" href="#awesome-ai-agents" aria-label="Permalink to &quot;awesome-ai-agents&quot;">​</a></h1><blockquote><p>A list of AI autonomous agents</p></blockquote><p><strong>Source:</strong> <a href="https://github.com/e2b-dev/awesome-ai-agents" target="_blank" rel="noreferrer">github.com/e2b-dev/awesome-ai-agents</a> · ★ 30.3k · maintained by E2B · docs at <a href="https://docs.e2b.dev" target="_blank" rel="noreferrer">docs.e2b.dev</a></p><p>The shortest description and the most dated topic list in this index. Its GitHub topics still reference <code>autogpt</code>, <code>babyagi</code> and <code>gpt-engineer</code> — the 2023 agent wave — while the stars say otherwise. 949 open PRs against 473 commits is the signature of a list whose contributor queue outgrew its maintainers.</p><h2 id="what-s-inside" tabindex="-1">What&#39;s inside <a class="header-anchor" href="#what-s-inside" aria-label="Permalink to &quot;What&#39;s inside&quot;">​</a></h2><p>Unlike every other list here, this one has <strong>no categories</strong>. It is a flat, alphabetical catalogue of <strong>215 projects</strong>, each given its own <code>##</code> heading, a link, and a short description.</p><p>It is also a catalogue of <em>products</em>, not only code: of the 215, only <strong>75 link to a GitHub repository</strong>. The other 140 point at the project&#39;s own site — <code>agentgpt.reworkd.ai</code>, <code>agpt.co</code>, <code>replit.com/@user/…</code>, and a striking number of bare <code>twitter.com/status/…</code> links from 2023. So the &quot;open source&quot; framing is only accurate for about a third of the list, and the repository index built from this source carries the 75 that qualify.</p><ul><li><strong>Framing sections</strong> — &quot;Have anything to add?&quot;, &quot;Who&#39;s behind this?&quot;, &quot;Check out E2B — Code Interpreting for AI apps&quot;</li><li><strong>Projects</strong> — one <code>##</code> per project, A→Z</li></ul><p>The alphabetical run is itself the clearest evidence of the list&#39;s vintage. Entries cluster heavily around the 2023 name-collision wave: <code>AgentGPT</code>, <code>AutoGPT</code>, <code>BabyAGI</code>, <code>BabyBeeAGI</code>, <code>BabyCatAGI</code>, <code>BabyDeerAGI</code>, <code>BabyElfAGI</code>, <code>BabyCommandAGI</code>, <code>BabyFoxAGI</code> — nine BabyAGI forks, several of which exist only as tweets. Later entries (<code>Adala</code>, <code>AutoGen</code>, <code>Aider</code>) are the ones still worth reading.</p><p>The README also carries a visible <code>&lt;!-- TBD --&gt;</code> comment block listing projects queued for addition and entries deferred pending review. It is an honest work-in-progress, but a published TODO block tells you the maintainer does not treat the README as finished.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>GitHub topics still read <code>autogpt</code>, <code>babyagi</code>, <code>gpt-engineer</code> — the 2023 agent wave. 949 open PRs against 473 commits is the signature of a contributor queue that outgrew its maintainers.</li><li>E2B&#39;s own README links point at <code>docs.e2b.dev</code> with referral parameters — the list is a funnel.</li><li>Licence is a bare <code>LICENSE.md</code> link with no recognised SPDX identifier in the repo header.</li><li>Because there are no categories, this is the least searchable list in the index. The alphabetical structure means you scan it; you cannot filter it.</li></ul>',12)),r(t)])}const f=o(c,[["render",d]]);export{b as __pageData,f as default};
